defmodule ProductElement do
  @enforce_keys [:product]
  defstruct [:product]

  @type t :: %__MODULE__{
          product: ProductProduct.t()
        }

  def from_map(m) do
    %ProductElement{
      product: ProductProduct.from_map(m["product"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "product" => ProductProduct.to_map(struct.product),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end

